<?php require 'includes/functions.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$key=post('cart_key')?:post('id');try{[$id,$variant]=cart_identity($key);}catch(RuntimeException $error){if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json')){http_response_code(422);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>false,'message'=>t($error->getMessage())],JSON_UNESCAPED_UNICODE);exit;}flash($error->getMessage());go('cart.php');}if(post('variant_id')!=='')$variant=(int)post('variant_id');$cartKey=$variant?$id.':'.$variant:$id;$qty=filter_var(post('quantity'),FILTER_VALIDATE_INT);$p=q('SELECT p.* FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1 AND c.active=1',[$id])->fetch();$action=post('action');$ok=false;if($p&&$p['variants_enabled']){$v=q('SELECT * FROM product_variants WHERE id=? AND product_id=? AND active=1',[$variant,$id])->fetch();if(!$v)$p=null;else $p['stock']=$v['stock'];}elseif($variant)$p=null;
if($action==='remove'){unset($_SESSION['cart'][$cartKey]);$message='นำสินค้าออกจากตะกร้าแล้ว';$ok=true;}
elseif(in_array($action,['add','update'],true)&&$p&&$qty!==false&&$qty>0){$new=$action==='add'?($_SESSION['cart'][$cartKey]??0)+$qty:$qty;if($new<=$p['stock']){$_SESSION['cart'][$cartKey]=$new;$message='อัปเดตตะกร้าสำเร็จ';$ok=true;}else $message='จำนวนสินค้าเกินสต็อก';}else $message='ข้อมูลสินค้าหรือจำนวนไม่ถูกต้อง';
if(str_contains($_SERVER['HTTP_ACCEPT']??'','application/json')){http_response_code($ok?200:422);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>$ok,'message'=>t($message),'count'=>array_sum($_SESSION['cart']??[])],JSON_UNESCAPED_UNICODE);exit;}
flash($message);go('cart.php');}
$items=cart_items();$sum=0;require 'includes/header.php';?><div class="page-heading"><span class="eyebrow"><?=e(t('สิ่งที่คุณเลือกให้คนสำคัญ'))?></span><h1><?=e(t('ตะกร้าสินค้า'))?></h1></div><?php if(!$items):?><div class="empty"><h2><?=e(t('ตะกร้ายังว่างอยู่'))?></h2><a class="button" href="products.php"><?=e(t('เลือกซื้อสินค้า'))?></a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th><?=e(t('สินค้า'))?></th><th><?=e(t('ราคา'))?></th><th><?=e(t('จำนวน'))?></th><th><?=e(t('รวม'))?></th><th></th></tr></thead><tbody><?php foreach($items as $p):$sum+=cents($p['price'])*$p['quantity'];?><tr><td><a class="cart-product" href="product_detail.php?id=<?=(int)$p['id']?>"><?=product_image_html($p,'',true,'80px')?><span><?=e(localized_name($p))?> <?=e(($p['variant_color']??'').' '.($p['variant_size']??''))?><small><?=e(product_image_note($p))?></small></span></a></td><td><?=money($p['price'])?></td><td><form method="post" class="inline"><?=csrf()?><input type="hidden" name="cart_key" value="<?=e($p['cart_key'])?>"><input name="quantity" type="number" min="1" max="<?=$p['stock']?>" value="<?=$p['quantity']?>" required><button name="action" value="update"><?=e(t('อัปเดต'))?></button></form></td><td><?=money(cents($p['price'])*$p['quantity']/100)?></td><td><form method="post"><?=csrf()?><input type="hidden" name="cart_key" value="<?=e($p['cart_key'])?>"><button class="text-button" name="action" value="remove"><?=e(t('ลบ'))?></button></form></td></tr><?php endforeach ?></tbody></table></div><div class="summary"><h2><?=e(t('รวมสินค้า'))?> <?=money($sum/100)?></h2><p><?=e(t('ค่าจัดส่ง ฿50 / ฟรีเมื่อยอดสินค้าครบ ฿1,000'))?></p><a class="button" href="checkout.php"><?=e(t('ดำเนินการสั่งซื้อ ↗'))?></a></div><?php endif;require 'includes/footer.php';?>
